style.css:
@-moz-document domain("roblox.com") {
/* Avatar wardrobe container */
  #avatar-wearables, #avatar-editor, .avatar-section {
    background-color: #f9f9f9 !important;
    border: 1px solid #ccc !important;
    padding: 15px !important;
    box-shadow: none !important;
  }

  /* Grid items for wearables */
  .avatar-wearable-item, .wearable-item-card {
    border: 1px solid #bbb !important;
    background-color: white !important;
    box-shadow: none !important;
    border-radius: 0 !important;
    margin: 6px !important;
    padding: 8px !important;
    transition: background-color 0.2s ease;
  }
  .avatar-wearable-item:hover, .wearable-item-card:hover {
    background-color: #dbe9ff !important;
  }

  /* Item icons */
  .avatar-wearable-item img, .wearable-item-card img {
    border: 1px solid #999 !important;
    border-radius: 2px !important;
    max-width: 100% !important;
  }

  /* Section headers */
  .avatar-section h2, .wardrobe-header {
    font-weight: bold !important;
    color: #003d99 !important;
    border-bottom: 2px solid #0055cc !important;
    padding-bottom: 4px !important;
    margin-bottom: 12px !important;
  }

  /* Sidebar tweaks */
  .sidebar, .avatar-sidebar {
    background-color: #e0e0e0 !important;
    border-right: 1px solid #ccc !important;
    padding: 12px !important;
  }

  /* Button styling */
  button, .btn-primary, .btn-secondary {
    background-color: #0055cc !important;
    color: white !important;
    border-radius: 2px !important;
    border: none !important;
    padding: 6px 12px !important;
    font-size: 13px !important;
  }

  /* Text and labels */
  .avatar-wearable-label, .wardrobe-item-name {
    font-size: 13px !important;
    color: #222 !important;
  }

  /* Remove extra modern shadows and rounded corners */
  * {
    box-shadow: none !important;
    border-radius: 0 !important;
  }
}
